import telebotfrom telebot import typesimport osimport sqlite3from datetime import datetimefrom flask import Flask, requestTOKEN = "8603985557:AAHBEt7Sz9xM7aoI7SR5jANjcWrAKzqzXz8"ADMIN_ID = 8692037031bot = telebot.TeleBot(TOKEN)app = Flask(__name__)# База данныхconn = sqlite3.connect('applications.db', check_same_thread=False)cursor = conn.cursor()cursor.execute('''CREATE TABLE IF NOT EXISTS applications     (id INTEGER PRIMARY KEY, telegram_id INTEGER, name TEXT, phone TEXT,      visa TEXT, arc TEXT, income TEXT, amount TEXT, purpose TEXT, date TEXT)''')conn.commit()user_data = {}# ====================== WEBHOOK ======================@app.route('/' + TOKEN, methods=['POST'])def webhook():    json_str = request.get_data().decode('UTF-8')    update = telebot.types.Update.de_json(json_str)    bot.process_new_updates([update])    return '', 200# ====================== КОМАНДЫ ======================@bot.message_handler(commands=['start'])def start(message):    markup = types.InlineKeyboardMarkup(row_width=1)    markup.add(types.InlineKeyboardButton("📋 Подать заявку на кредит", callback_data="new_form"))    markup.add(types.InlineKeyboardButton("ℹ️ Условия для иностранцев", callback_data="info"))    bot.send_message(message.chat.id, "👋 <b>Бот по кредитам в Корее</b>", reply_markup=markup, parse_mode='HTML')@bot.callback_query_handler(func=lambda call: True)def callback_handler(call):    chat_id = call.message.chat.id    data = call.data    bot.answer_callback_query(call.id)    if data == "new_form":        user_data[chat_id] = {}        bot.send_message(chat_id, "👤 Напишите ваше полное имя:")        user_data[chat_id]['step'] = 'name'    elif data == "info":        bot.send_message(chat_id, "Для иностранцев нужны:\n• Виза\n• ARC\n• Доход")    elif data.startswith("visa_"):        visa = data.split("_")[1]        user_data[chat_id]['visa'] = visa        bot.send_message(chat_id, f"✅ Виза: <b>{visa}</b>\n\nНапишите номер ARC (или «Нет»):", parse_mode='HTML')        user_data[chat_id]['step'] = 'arc'# ... (остальную форму можешь добавить позже)if __name__ == "__main__":    bot.remove_webhook()    bot.set_webhook(url=os.getenv('RENDER_EXTERNAL_URL') + "/" + TOKEN)    print("✅ Webhook установлен")    app.run(host="0.0.0.0", port=int(os.environ.get("PORT", 5000)))